@namespace sv_63aa0b805e464d44bd26e1caf7ff6037.Components.Apply

<fieldset class="work-entry">
    <legend>Position @(Index + 1)</legend>

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" value="@Entry.Company" @oninput="OnCompanyInput" class="form-control" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" value="@Entry.Title" @oninput="OnTitleInput" class="form-control" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@FormatDate(Entry.StartDate)" @onchange="OnStartDateChange" class="form-control" />
        </div>

        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@FormatNullableDate(Entry.EndDate)" @onchange="OnEndDateChange" class="form-control" disabled="@IsCurrent" />
        </div>

        <div class="form-group checkbox-group">
            <label>
                <input type="checkbox" checked="@IsCurrent" @onchange="HandleCurrentChanged" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea value="@Entry.Description" @oninput="OnDescriptionInput" class="form-control" rows="3"></textarea>
    </div>

    @if (CanRemove)
    {
        <button type="button" class="btn btn-danger btn-sm" @onclick="OnRemove">Remove</button>
    }
</fieldset>

@code {
    [Parameter, EditorRequired] public WorkEntryModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryModel> OnChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.IsCurrent;

    private static string FormatDate(DateTime date) => date.ToString("yyyy-MM-dd");
    private static string FormatNullableDate(DateTime? date) => date?.ToString("yyyy-MM-dd") ?? string.Empty;

    private Task OnCompanyInput(ChangeEventArgs e) =>
        OnChanged.InvokeAsync(Entry with { Company = GetString(e) });

    private Task OnTitleInput(ChangeEventArgs e) =>
        OnChanged.InvokeAsync(Entry with { Title = GetString(e) });

    private Task OnDescriptionInput(ChangeEventArgs e) =>
        OnChanged.InvokeAsync(Entry with { Description = GetString(e) });

    private Task OnStartDateChange(ChangeEventArgs e)
    {
        var val = e.Value?.ToString();
        if (DateTime.TryParse(val, out var date))
            return OnChanged.InvokeAsync(Entry with { StartDate = date });
        return Task.CompletedTask;
    }

    private Task OnEndDateChange(ChangeEventArgs e)
    {
        var val = e.Value?.ToString();
        DateTime? endDate = string.IsNullOrEmpty(val) ? null : DateTime.TryParse(val, out var d) ? d : null;
        return OnChanged.InvokeAsync(Entry with { EndDate = endDate });
    }

    private Task HandleCurrentChanged(ChangeEventArgs e)
    {
        var isCurrent = (bool)(e.Value ?? false);
        var updated = Entry with { IsCurrent = isCurrent, EndDate = isCurrent ? null : Entry.EndDate };
        return OnChanged.InvokeAsync(updated);
    }

    private static string GetString(ChangeEventArgs e) => e.Value?.ToString() ?? string.Empty;

    public record WorkEntryModel(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description, bool IsCurrent);
}

